import{_ as e,o as t,c as n,a3 as s}from"./chunks/framework.BlfGB29P.js";const u=JSON.parse('{"title":"多租户架构","description":"从可信租户上下文、数据与计算隔离、部署拓扑、配额和生命周期出发，设计贯穿 Agent 全链路的租户边界。","frontmatter":{"title":"多租户架构","description":"从可信租户上下文、数据与计算隔离、部署拓扑、配额和生命周期出发，设计贯穿 Agent 全链路的租户边界。","verified_at":"2026-08-03","source":["https://docs.aws.amazon.com/wellarchitected/latest/saas-lens/saas-lens.html","https://www.postgresql.org/docs/current/ddl-rowsecurity.html","https://www.postgresql.org/docs/current/ddl-constraints.html","https://opentelemetry.io/docs/concepts/"],"article":{"type":"decision","structure":"decision"}},"headers":[],"relativePath":"py-agent/architecture/system-architecture/multi-tenancy-architecture.md","filePath":"py-agent/architecture/system-architecture/multi-tenancy-architecture.md","lastUpdated":1786083160000}'),r={name:"py-agent/architecture/system-architecture/multi-tenancy-architecture.md"};function l(i,a,d,o,h,p){return t(),n("div",null,[...a[0]||(a[0]=[s(`<h1 id="多租户架构" tabindex="-1">多租户架构 <a class="header-anchor" href="#多租户架构" aria-label="Permalink to &quot;多租户架构&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>多租户系统让多个客户组织共享一套产品能力，同时要求每个租户的数据、权限、资源和配置保持可解释的边界。对 Agent 应用而言，这条边界还要穿过模型上下文、工具调用、Checkpoint、长期记忆、向量索引和 Trace；只给业务表增加 <code>tenant_id</code>，并不能阻止跨租户检索、缓存串读或共享工具越权。</p><p>本文讨论多租户系统的架构选择和端到端隔离。认证代码、数据库查询和 Redis Key 的具体实现分别由“Agent 应用工程”中的服务、数据和协调文章展开；本文重点回答隔离放在哪里、采用哪种拓扑，以及怎样证明边界成立。</p><h2 id="_1-租户边界" tabindex="-1">1. 租户边界 <a class="header-anchor" href="#_1-租户边界" aria-label="Permalink to &quot;1. 租户边界&quot;">​</a></h2><h3 id="_1-1-tenant、user-与-principal" tabindex="-1">1.1 Tenant、User 与 Principal <a class="header-anchor" href="#_1-1-tenant、user-与-principal" aria-label="Permalink to &quot;1.1 Tenant、User 与 Principal&quot;">​</a></h3><p><code>Tenant</code> 是数据、策略、计费和资源隔离边界；<code>User</code> 是人或服务身份；<code>Principal</code> 是一次请求中经过认证、携带当前租户成员关系和权限的可信主体。一个用户可能属于多个租户，因此登录身份不自动等于当前租户。</p><h3 id="_1-2-当前租户如何确定" tabindex="-1">1.2 当前租户如何确定 <a class="header-anchor" href="#_1-2-当前租户如何确定" aria-label="Permalink to &quot;1.2 当前租户如何确定&quot;">​</a></h3><p>当前租户必须来自受信任的选择和校验流程：客户端提出租户标识，服务端验证用户确实属于该租户，再建立不可由模型改写的 Runtime Context。Prompt、请求正文中的任意字段或工具参数都不能单独决定租户身份。</p><h3 id="_1-3-隔离与共享" tabindex="-1">1.3 隔离与共享 <a class="header-anchor" href="#_1-3-隔离与共享" aria-label="Permalink to &quot;1.3 隔离与共享&quot;">​</a></h3><p>多租户并不意味着所有资源都共享。可以共享应用进程而隔离数据库，也可以共享数据库而隔离行，还可以为特定租户提供独立 Cell。架构需要逐层说明共享什么、隔离什么，以及共享资源耗尽时谁受影响。</p><h2 id="_2-隔离表面" tabindex="-1">2. 隔离表面 <a class="header-anchor" href="#_2-隔离表面" aria-label="Permalink to &quot;2. 隔离表面&quot;">​</a></h2><h3 id="_2-1-业务数据" tabindex="-1">2.1 业务数据 <a class="header-anchor" href="#_2-1-业务数据" aria-label="Permalink to &quot;2.1 业务数据&quot;">​</a></h3><p>资源查询、唯一约束、外键、幂等键和审计记录都包含租户维度。按裸 <code>resource_id</code> 查询后再检查租户，会扩大时序、错误信息和编程遗漏造成的泄露风险。</p><h3 id="_2-2-agent-执行状态" tabindex="-1">2.2 Agent 执行状态 <a class="header-anchor" href="#_2-2-agent-执行状态" aria-label="Permalink to &quot;2.2 Agent 执行状态&quot;">​</a></h3><p>业务 Thread、Run、Task、LangGraph <code>thread_id</code> 和 Checkpoint 都要能追溯到租户。State 中的 <code>tenant_id</code> 只能作为关联值，真正授权仍来自受信 Runtime Context 和数据层约束。</p><h3 id="_2-3-rag-与记忆" tabindex="-1">2.3 RAG 与记忆 <a class="header-anchor" href="#_2-3-rag-与记忆" aria-label="Permalink to &quot;2.3 RAG 与记忆&quot;">​</a></h3><p>文档、Chunk、Embedding、检索过滤、Store Namespace 和长期记忆都携带租户与 ACL。权限过滤必须在召回阶段完成；先召回其他租户内容再要求模型忽略，数据已经越过边界。</p><h3 id="_2-4-缓存、队列与制品" tabindex="-1">2.4 缓存、队列与制品 <a class="header-anchor" href="#_2-4-缓存、队列与制品" aria-label="Permalink to &quot;2.4 缓存、队列与制品&quot;">​</a></h3><p>缓存 Key、限流计数、队列分区、对象存储路径和下载链接都需要租户命名空间。队列消息还要保存可信主体或受限委托引用，使后台 Worker 不依赖原始 HTTP 请求继续授权。</p><h3 id="_2-5-模型与工具" tabindex="-1">2.5 模型与工具 <a class="header-anchor" href="#_2-5-模型与工具" aria-label="Permalink to &quot;2.5 模型与工具&quot;">​</a></h3><p>模型网关按租户执行允许的供应商、地域、预算和数据策略。工具执行层重新验证主体、动作和资源，不因为该工具已经出现在 Agent 的 Tool Registry 中就默认当前租户有权调用。</p><h3 id="_2-6-遥测与运营" tabindex="-1">2.6 遥测与运营 <a class="header-anchor" href="#_2-6-遥测与运营" aria-label="Permalink to &quot;2.6 遥测与运营&quot;">​</a></h3><p>Trace 需要关联租户才能定位问题和归集成本，但日志、指标标签和支持界面必须最小披露。高基数租户 ID 更适合保存在 Trace 或受控明细中，不应无差别成为所有时序指标标签。</p><h2 id="_3-隔离拓扑候选" tabindex="-1">3. 隔离拓扑候选 <a class="header-anchor" href="#_3-隔离拓扑候选" aria-label="Permalink to &quot;3. 隔离拓扑候选&quot;">​</a></h2><h3 id="_3-1-共享表" tabindex="-1">3.1 共享表 <a class="header-anchor" href="#_3-1-共享表" aria-label="Permalink to &quot;3.1 共享表&quot;">​</a></h3><p>租户共享数据库和 Schema，每行包含 <code>tenant_id</code>。它成本最低、升级一致，但所有查询、关联、唯一约束、索引和缓存都必须正确携带租户条件。数据库 Row-Level Security（RLS）可以按连接中的可信上下文强制行策略，适合作为纵深控制，但不能替代应用的明确租户契约。</p><h3 id="_3-2-独立-schema" tabindex="-1">3.2 独立 Schema <a class="header-anchor" href="#_3-2-独立-schema" aria-label="Permalink to &quot;3.2 独立 Schema&quot;">​</a></h3><p>每个租户或租户组使用独立 Schema。它提高逻辑隔离，仍可共享数据库实例；代价是迁移数量、连接搜索路径、Schema 漂移和运营工具更复杂。适合租户数量有限且需要更强逻辑边界的场景。</p><h3 id="_3-3-独立数据库" tabindex="-1">3.3 独立数据库 <a class="header-anchor" href="#_3-3-独立数据库" aria-label="Permalink to &quot;3.3 独立数据库&quot;">​</a></h3><p>每个租户或租户组使用独立数据库。备份、恢复、加密和容量可以分别管理，但连接池、迁移、监控和跨租户统计成本明显增加。它适合高价值租户、监管要求或明显的资源隔离需求。</p><h3 id="_3-4-cell-架构" tabindex="-1">3.4 Cell 架构 <a class="header-anchor" href="#_3-4-cell-架构" aria-label="Permalink to &quot;3.4 Cell 架构&quot;">​</a></h3><p>多个租户被分配到独立 Cell，每个 Cell 包含应用、数据库、缓存、队列和索引。控制面负责租户到 Cell 的映射和配置，数据面只处理本 Cell 流量。Cell 能限制单次故障范围，也需要处理租户迁移、全局目录和跨 Cell 运维。</p><h3 id="_3-5-独立账户或部署" tabindex="-1">3.5 独立账户或部署 <a class="header-anchor" href="#_3-5-独立账户或部署" aria-label="Permalink to &quot;3.5 独立账户或部署&quot;">​</a></h3><p>租户拥有独立云账户、网络或完整部署，隔离最强，成本和发布复杂度最高。通常只用于合同、数据主权或威胁模型明确要求的租户，而不是默认方案。</p><h2 id="_4-拓扑选择" tabindex="-1">4. 拓扑选择 <a class="header-anchor" href="#_4-拓扑选择" aria-label="Permalink to &quot;4. 拓扑选择&quot;">​</a></h2><table tabindex="0"><thead><tr><th>决策维度</th><th>共享表</th><th>独立 Schema</th><th>独立数据库</th><th>Cell</th><th>独立部署</th></tr></thead><tbody><tr><td>数据隔离</td><td>基础</td><td>中</td><td>强</td><td>强</td><td>最强</td></tr><tr><td>故障隔离</td><td>弱</td><td>弱至中</td><td>强</td><td>强</td><td>最强</td></tr><tr><td>租户数量适应性</td><td>高</td><td>中</td><td>中低</td><td>高</td><td>低</td></tr><tr><td>迁移与发布成本</td><td>最低</td><td>中</td><td>高</td><td>高</td><td>最高</td></tr><tr><td>单租户恢复</td><td>较复杂</td><td>中</td><td>容易</td><td>取决于 Cell</td><td>最容易</td></tr><tr><td>资源定制</td><td>弱</td><td>中</td><td>强</td><td>按 Cell</td><td>最强</td></tr><tr><td>适用场景</td><td>大量标准租户</td><td>有限租户、逻辑隔离</td><td>高价值或监管租户</td><td>大规模与故障域</td><td>极高隔离要求</td></tr></tbody></table><p>隔离级别由数据分类、合规、规模、故障损失、资源噪声和商业承诺共同决定。可以采用混合策略：大多数租户使用共享 Cell，少数租户进入独立数据库或部署，但不同等级必须由确定规则分配并进入合同和运行文档。</p><h2 id="_5-租户上下文传播" tabindex="-1">5. 租户上下文传播 <a class="header-anchor" href="#_5-租户上下文传播" aria-label="Permalink to &quot;5. 租户上下文传播&quot;">​</a></h2><h3 id="_5-1-请求链" tabindex="-1">5.1 请求链 <a class="header-anchor" href="#_5-1-请求链" aria-label="Permalink to &quot;5.1 请求链&quot;">​</a></h3><p>一条可信链路可以表示为：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Access Token</span></span>
<span class="line"><span>  -&gt; Authentication</span></span>
<span class="line"><span>  -&gt; Membership / Tenant Selection</span></span>
<span class="line"><span>  -&gt; Principal(tenant_id, subject_id, scopes, region)</span></span>
<span class="line"><span>  -&gt; Use Case</span></span>
<span class="line"><span>  -&gt; Agent Runtime Context</span></span>
<span class="line"><span>  -&gt; Repository / Retriever / Tool Gateway</span></span>
<span class="line"><span>  -&gt; Audit and Trace</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p>每个边界只接受上游经过验证的上下文，并在进入数据库、索引或外部工具时重新执行自己的约束。模型只看到完成任务所需的租户数据，不拥有选择或修改租户的能力。</p><h3 id="_5-2-后台任务" tabindex="-1">5.2 后台任务 <a class="header-anchor" href="#_5-2-后台任务" aria-label="Permalink to &quot;5.2 后台任务&quot;">​</a></h3><p>HTTP 请求结束后，Worker 仍需要可信身份。任务记录应保存租户、发起主体、授权范围或受限委托引用，以及策略版本。Worker 开始执行时重新检查租户状态、权限撤销和任务范围，不能永久复用过期访问令牌。</p><h3 id="_5-3-控制面与数据面" tabindex="-1">5.3 控制面与数据面 <a class="header-anchor" href="#_5-3-控制面与数据面" aria-label="Permalink to &quot;5.3 控制面与数据面&quot;">​</a></h3><p>控制面管理租户开通、Cell 分配、模型策略、配额、密钥和功能；数据面处理用户任务。控制面配置要版本化并发布为可验证快照。控制面不可用时，数据面使用最后一个已批准版本或按风险关闭能力，不能默认为最高权限。</p><h2 id="_6-资源与配额隔离" tabindex="-1">6. 资源与配额隔离 <a class="header-anchor" href="#_6-资源与配额隔离" aria-label="Permalink to &quot;6. 资源与配额隔离&quot;">​</a></h2><h3 id="_6-1-多层预算" tabindex="-1">6.1 多层预算 <a class="header-anchor" href="#_6-1-多层预算" aria-label="Permalink to &quot;6.1 多层预算&quot;">​</a></h3><p>同时设置平台、租户、用户和单次 Run 的请求率、并发、Token、工具调用和费用预算。只有限制单请求 Token，仍可能被大量并发任务耗尽共享模型配额或数据库连接。</p><h3 id="_6-2-公平调度" tabindex="-1">6.2 公平调度 <a class="header-anchor" href="#_6-2-公平调度" aria-label="Permalink to &quot;6.2 公平调度&quot;">​</a></h3><p>队列需要观察每个租户的积压和最老任务，使用加权公平、并发上限或独立队列避免噪声邻居。商业优先级可以影响调度顺序，但不能绕过地域、权限或安全门禁。</p><h3 id="_6-3-热租户与迁移" tabindex="-1">6.3 热租户与迁移 <a class="header-anchor" href="#_6-3-热租户与迁移" aria-label="Permalink to &quot;6.3 热租户与迁移&quot;">​</a></h3><p>识别 CPU、数据库连接、向量检索、模型配额、对象存储和网络出口的租户级消耗。当限流无法满足承诺时，可以把租户迁移到独立数据库或 Cell；迁移需要双读/校验、流量切换、回退和旧副本清理，不能只修改路由表。</p><h2 id="_7-租户生命周期" tabindex="-1">7. 租户生命周期 <a class="header-anchor" href="#_7-租户生命周期" aria-label="Permalink to &quot;7. 租户生命周期&quot;">​</a></h2><h3 id="_7-1-开通" tabindex="-1">7.1 开通 <a class="header-anchor" href="#_7-1-开通" aria-label="Permalink to &quot;7.1 开通&quot;">​</a></h3><p>开通流程创建租户标识、初始成员、数据位置、配额、密钥引用和审计记录。异步建立数据库、索引或 Cell 时，租户状态保持 <code>provisioning</code>，不能在依赖尚未就绪时暴露完整功能。</p><h3 id="_7-2-配置与密钥" tabindex="-1">7.2 配置与密钥 <a class="header-anchor" href="#_7-2-配置与密钥" aria-label="Permalink to &quot;7.2 配置与密钥&quot;">​</a></h3><p>租户配置需要 Schema、版本、默认值和审批。自带模型或外部系统凭据按租户加密、轮换和审计，Secret 不进入 Prompt、State 或普通日志。</p><h3 id="_7-3-导出、迁移与删除" tabindex="-1">7.3 导出、迁移与删除 <a class="header-anchor" href="#_7-3-导出、迁移与删除" aria-label="Permalink to &quot;7.3 导出、迁移与删除&quot;">​</a></h3><p>租户导出和删除覆盖业务数据、Checkpoint、记忆、索引、缓存、制品和评测副本。删除进入可观察状态机并保留允许的审计证据；租户停用后还要撤销服务身份、Webhook、签名 URL 和后台任务。</p><h2 id="_8-参考决策-企业知识库-saas" tabindex="-1">8. 参考决策：企业知识库 SaaS <a class="header-anchor" href="#_8-参考决策-企业知识库-saas" aria-label="Permalink to &quot;8. 参考决策：企业知识库 SaaS&quot;">​</a></h2><h3 id="_8-1-约束" tabindex="-1">8.1 约束 <a class="header-anchor" href="#_8-1-约束" aria-label="Permalink to &quot;8.1 约束&quot;">​</a></h3><p>假设产品服务数千家中小企业，少数金融客户要求独立数据库；文档和索引必须位于指定地域；所有租户共享模型网关，但模型供应商策略可不同。</p><h3 id="_8-2-选择" tabindex="-1">8.2 选择 <a class="header-anchor" href="#_8-2-选择" aria-label="Permalink to &quot;8.2 选择&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>普通租户</span></span>
<span class="line"><span>  -&gt; 按地域进入共享 Cell</span></span>
<span class="line"><span>  -&gt; PostgreSQL 共享表 + tenant_id + 复合约束</span></span>
<span class="line"><span>  -&gt; Cell 内独立向量索引 Namespace 和对象前缀</span></span>
<span class="line"><span></span></span>
<span class="line"><span>受监管租户</span></span>
<span class="line"><span>  -&gt; 同地域专用 Cell 或独立数据库</span></span>
<span class="line"><span>  -&gt; 独立模型凭据和更严格观测保留</span></span>
<span class="line"><span></span></span>
<span class="line"><span>统一控制面</span></span>
<span class="line"><span>  -&gt; tenant -&gt; cell 映射</span></span>
<span class="line"><span>  -&gt; 配额、模型策略和功能版本</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br></div></div><p>共享表降低大量普通租户的运营成本，地域 Cell 限制数据和故障范围，受监管租户按合同升级隔离。代价是控制面、租户迁移和两种数据拓扑都需要测试与运维。</p><h3 id="_8-3-不变量" tabindex="-1">8.3 不变量 <a class="header-anchor" href="#_8-3-不变量" aria-label="Permalink to &quot;8.3 不变量&quot;">​</a></h3><ul><li>请求只能访问 Principal 当前租户的资源；</li><li>Retriever 在召回前执行租户和 ACL 过滤；</li><li>Checkpoint、Store、缓存和制品都带租户命名空间；</li><li>工具网关重新授权资源，不信任模型参数；</li><li>任何跨租户管理操作都需要独立管理员权限和审计；</li><li>Cell 或控制面故障不能让数据面退回无租户过滤模式。</li></ul><h2 id="_9-验证与运营" tabindex="-1">9. 验证与运营 <a class="header-anchor" href="#_9-验证与运营" aria-label="Permalink to &quot;9. 验证与运营&quot;">​</a></h2><h3 id="_9-1-隔离测试" tabindex="-1">9.1 隔离测试 <a class="header-anchor" href="#_9-1-隔离测试" aria-label="Permalink to &quot;9.1 隔离测试&quot;">​</a></h3><p>为每类资源建立两个租户的负面测试：使用租户 A 的身份读取租户 B 的业务记录、Checkpoint、记忆、向量、缓存、制品和工具资源，期望全部在数据进入模型前被拒绝。测试裸 ID、猜测 ID、缓存命中、后台重试和管理员接口，而不只测试正常 HTTP 路由。</p><h3 id="_9-2-故障与容量测试" tabindex="-1">9.2 故障与容量测试 <a class="header-anchor" href="#_9-2-故障与容量测试" aria-label="Permalink to &quot;9.2 故障与容量测试&quot;">​</a></h3><p>让一个租户产生高并发、长查询、超大文档和模型重试，验证其他租户的 SLO、队列公平和预算仍成立。模拟 Cell、控制面和租户专用数据库不可用，确认故障不会无边界扩散。</p><h3 id="_9-3-运行指标" tabindex="-1">9.3 运行指标 <a class="header-anchor" href="#_9-3-运行指标" aria-label="Permalink to &quot;9.3 运行指标&quot;">​</a></h3><p>观察每租户的成功任务、p95、Token、工具调用、配额拒绝、最老队列任务、索引水位和存储增长。指标用于公平与容量分析，不应让支持人员默认看到所有租户正文。</p><h2 id="_10-常见误区与复查" tabindex="-1">10. 常见误区与复查 <a class="header-anchor" href="#_10-常见误区与复查" aria-label="Permalink to &quot;10. 常见误区与复查&quot;">​</a></h2><ol><li><strong>每张表有 <code>tenant_id</code> 就完成隔离</strong>：Checkpoint、索引、缓存、队列和工具仍可能串租户。</li><li><strong>登录用户就是租户</strong>：一个用户可能属于多个组织，当前租户需要服务端验证。</li><li><strong>RLS 可以替代应用设计</strong>：它是纵深控制，仍需要可信上下文和正确连接会话。</li><li><strong>独立数据库一定最安全</strong>：错误凭据、共享模型上下文和运营界面仍可造成泄露。</li><li><strong>高价租户可以跳过限制</strong>：商业优先级不能覆盖安全和数据政策。</li></ol><p>当租户数量、数据分类、地域、故障损失、热租户比例或商业隔离承诺变化时，重新评估拓扑。多租户架构的完成标准不是画出共享或独立数据库，而是证明同一租户边界在请求、状态、检索、工具、存储和运营链路中始终成立。</p>`,79)])])}const b=e(r,[["render",l]]);export{u as __pageData,b as default};
